VoiceAssistantService::~VoiceAssistantService(){disable();tts_.kill();tts_.waitForFinished(1500);}
bool VoiceAssistantService::authorized()const{return session_->can("inspect")&&owner_==session_->userId();}
bool VoiceAssistantService::busy()const{return QStringList{"recognizing","thinking","answering","speaking"}.contains(state_);}
QString VoiceAssistantService::status()const{static const QHash<QString,QString> labels{{"off","语音助手未开启"},{"starting","正在连接麦克风"},{"armed","我在听"},{"waiting","等待其他操作完成"},{"listening","我在听"},{"recognizing","正在识别"},{"thinking","正在思考"},{"answering","正在回答"},{"speaking","正在说话"},{"muted","麦克风已暂停"},{"error","需要重试"}};return labels.value(state_,state_);}
void VoiceAssistantService::setState(const QString&s){state_=s;emit changed();}
void VoiceAssistantService::setVolume(int n){volume_=qBound(5,n,60);if(session_->loggedIn())QSettings().setValue("voiceAssistant/"+session_->userId()+"/volume",volume_);emit changed();}
void VoiceAssistantService::setSilenceMs(int n){silenceMs_=qBound(450,n,1500);if(input_)input_->setSilence(silenceMs_);if(session_->loggedIn())QSettings().setValue("voiceAssistant/"+session_->userId()+"/silence",silenceMs_);emit changed();}
void VoiceAssistantService::setContinuous(bool n){continuous_=true;n=true;if(session_->loggedIn())QSettings().setValue("voiceAssistant/"+session_->userId()+"/continuous",n);emit changed();}
void VoiceAssistantService::setMuted(bool n){if(muted_==n)return;muted_=n;cancelTurn();if(input_){input_->block();setState(n?"muted":"listening");if(!n&&requested_)input_->listen(false);}emit changed();}
