void VoiceAssistantService::releaseInput(){if(input_){auto *old=input_;input_=nullptr;disconnect(old,nullptr,this,nullptr);old->requestInterruption();connect(old,&QThread::finished,old,&QObject::deleteLater);if(!old->isRunning())old->deleteLater();else old->wait(100);}level_=0;wakeAvailable_=false;emit levelChanged();}
