 messages_.append({{"outgoing",true},{"body",q},{"audioPath",audioInput_},{"systemEvidenceJson",QString::fromUtf8(QJsonDocument::fromVariant(systemEvidence_).toJson(QJsonDocument::Compact))}});persist();bool spokenInput=!audioInput_.isEmpty();audioInput_.clear();QString request=prompt(q);if(spokenInput)request+="\n当前提问来自语音识别，可能含同音误字；若与前文设备明显不符，先简短确认所指设备，不自行猜测并给出处置结论。";assistantRow_=messages_.append({{"body",""},{"streaming",true},{"session_closed",ending},{"systemEvidenceJson",QString::fromUtf8(QJsonDocument::fromVariant(systemEvidence_).toJson(QJsonDocument::Compact))}});answer_.clear();speechBuffer_.clear();ttsIndex_=0;mergeName_="answer-"+QUuid::createUuid().toString(QUuid::WithoutBraces)+".wav";modelDone_=false;finishSent_=false;firstAudio_=firstText_=false;createTts();setState("thinking");if(ending){answer_="好的，已结束对话。";modelDone_=true;flushText();splitSpeech(true);finishTurn();return;}
 // Exact device/health lookups use the verified database result directly: no extra planning latency or invented verdict.
 if(systemEvidence_.value("relevant").toBool()&&(systemEvidence_.value("status")!="found"||(!systemEvidence_.value("asset_id").toString().isEmpty()&&QRegularExpression("正常|情况|状态|位置|型号").match(q).hasMatch()&&!QRegularExpression("措施|处理|已关闭|历史|报告|录音|趋势|原因|为什么").match(q).hasMatch()))){answer_=systemEvidence_.value("direct_answer").toString();modelDone_=true;flushText();splitSpeech(true);finishTurn();return;}
